    name: "Scheduled Database Migration",
    startAt: "2026-04-01T02:00:00Z",
    endAt: "2026-04-01T06:00:00Z",
    leadId: opsLead.then(opsLead => opsLead.id),
    showInSidebar: true,
    resolveOnEnd: true,
