import * as pulumi from "@pulumi/pulumi";
import * as incident from "@incident-io/pulumi";

const config = new pulumi.Config();
const partnerWebhookToken = config.require("partnerWebhookToken");
const partnerWebhookTokenSecret = new incident.Secret("partner_webhook_token", {
    name: "Partner webhook token",
    description: "Bearer token for the partner's incident webhook",
    valueWo: partnerWebhookToken,
    valueWoVersion: 1,
});
// The first way: put the secret's value inside a field's text.
//
// A field whose feature set ends in `_with_secrets` - which the webhook step's headers do -
// accepts a variable naming a secret by ID, and incident.io substitutes the value when the
// workflow runs. Write it as `{{ <secret id> }}` and reference the secret's `id`, never its
// value: Terraform is arranging for the value to be used, not handling it.
const authorizationHeader = incident.getRichTextOutput({
    markdown: pulumi.interpolate`Authorization: Bearer {{ ${partnerWebhookTokenSecret.id} }}`,
    featureSet: "plain_single_line_with_secrets",
});
const contentTypeHeader = incident.getRichText({
    markdown: "Content-Type: application/json",
    featureSet: "plain_single_line_with_secrets",
});
const webhookEndpoint = incident.getRichText({
    markdown: "https://partner.example.com/hooks/incident",
    featureSet: "plain_single_line",
});
const webhookBody = incident.getRichText({
    markdown: "{{ incident.name }} is now {{ incident.status }} at severity {{ incident.severity }}.\n",
    featureSet: "rich",
});
const notifyPartner = new incident.Workflow("notify_partner", {
    name: "Notify our partner of incident updates",
    trigger: "incident.updated",
    expressions: [],
    conditionGroups: [],
    steps: [{
        id: "01K5TSNDBF7KBZY9AFDKYXJM3N",
        name: "webhook.send",
        paramBindings: [
            {
                valueLiteral: webhookEndpoint.then(webhookEndpoint => webhookEndpoint.json),
            },
            {
                valueLiteral: "POST",
            },
            {
                values: [
                    authorizationHeader.json,
                    contentTypeHeader.then(contentTypeHeader => contentTypeHeader.json),
                ],
            },
            {
                valueLiteral: webhookBody.then(webhookBody => webhookBody.json),
            },
            {
                valueLiteral: partnerWebhookTokenSecret.id,
            },
            {},
            {},
        ],
    }],
    onceFors: ["incident"],
    privateIncidentScope: "none",
    continueOnStepError: false,
    runsOnIncidents: "newly_created_and_active",
    runsOnIncidentModes: ["standard"],
    state: "draft",
});
